/* From Uiverse.io by JaydipPrajapati1910 - Tags: white, black, card, box-shadow */
.__UIV_SCOPE__ .card {
  width: 190px;
  height: 254px;
  border-radius: 20px;
  padding: 2px;
  box-shadow: #111 0 1px 3px 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  position: relative;
  cursor: pointer;
}

.__UIV_SCOPE__ .card__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: linear-gradient(0deg, #000, #272727);
  color: #fff;
  border-radius: 17px;
  width: 100%;
  height: 100%;
  font-size: 20px;
  font-weight: 900;
}
